class Solution {
    public int missingInteger(int[] nums){
        Set<Integer> values=new HashSet<>();
        for(int value:nums)values.add(value);
        int sum=nums[0];
        for(int i=1;i<nums.length&&nums[i]==nums[i-1]+1;i++)sum+=nums[i];
        while(values.contains(sum))sum++;
        return sum;
    }
}

code.kotlin:
class Solution {
    fun missingInteger(nums:IntArray):Int{
        val values=nums.toHashSet();
        var sum=nums[0];
        var index=1;
        while(index<nums.size&&nums[index]==nums[index-1]+1){
            sum+=nums[index];
            index++
        };
        while(sum in values)sum++;
        return sum
    }
}

code.cpp:
class Solution {
    public:int missingInteger(vector<int>& nums){
        unordered_set<int> values(nums.begin(),nums.end());
        int sum=nums[0];
        for(int i=1;i<(int)nums.size()&&nums[i]==nums[i-1]+1;++i)sum+=nums[i];
        while(values.count(sum))++sum;
        return sum;
    }
};
